let company={},pricing={},state={pages:1,extras:new Set(),services:new Set(),quoteNumber:"",discount:0,documentType:"cotizacion",applyIva:false,editingQuoteId:null};
const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(Number(n)||0);
function escapeHtml(value){return String(value??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));}
const FALLBACK_PRICING={
  web:{name:'Diseño Web',description:'Desarrollo de sitio web profesional y responsive.',base:0,pagePrice:0,pagesIncluded:1,extras:[
    {id:'domain',name:'Dominio .cl / .com (1 año)',price:0},{id:'hosting',name:'Hosting (1 año)',price:0},{id:'ssl',name:'Certificado SSL',price:0},
    {id:'whatsapp',name:'Integración WhatsApp',price:0},{id:'form',name:'Formulario de contacto',price:0},{id:'seo',name:'SEO básico',price:0},{id:'maintenance',name:'Mantención mensual',price:0}
  ]},
  logo:{name:'Diseño de Logo',description:'Diseño de identidad gráfica principal.',price:0},
  branding:{name:'Branding',description:'Sistema visual de marca y lineamientos.',price:0},
  social:{name:'Creación de Redes Sociales',description:'Configuración y presentación profesional de perfiles.',price:0},
  maintenance:{name:'Mantención Web',description:'Actualizaciones, soporte y mantenimiento.',price:0},
  programming:{name:'Programación / Desarrollo a medida',description:'Funciones y desarrollos personalizados.',price:0},
  music:{name:'Producción Musical',description:'Servicio de producción musical según requerimiento.',price:0}
};
const FALLBACK_COMPANY={rut:'78.515.457-6',name:'ESTGARSTUDIO SpA',brand:'EstGar Studio SpA',representative:'ISMAEL ESTEBAN OSORIO GÁRATE',address:'Comuna de Paihuano, Región de Coquimbo, Chile',activity:'Diseño Web, Programación y Producción Musical',phone:'+569 6598 2665',email:'estgarstudio@gmail.com'};
async function loadJSON(path,fallback){try{const r=await fetch(path);if(!r.ok)throw new Error('HTTP '+r.status);return await r.json()}catch(e){return fallback}}
async function init(){
  try{company=await loadJSON('data/company.json',FALLBACK_COMPANY)}catch{company=FALLBACK_COMPANY}
  try{pricing=await loadJSON('data/pricing.json',FALLBACK_PRICING)}catch{pricing=FALLBACK_PRICING}
  try{const saved=localStorage.getItem('estgar_pricing');if(saved){const parsed=JSON.parse(saved);if(parsed&&typeof parsed==='object'&&Object.keys(parsed).length)pricing=parsed}}catch{}
  migrateClients();
  state.quoteNumber=nextQuoteNumber();
  renderServices();
  bind();
  if($('saveBtn'))$('saveBtn').onclick=saveQuote;
  setQuoteNumber();
  renderAll();
  showView('dashboard');
}
function nextQuoteNumber(){const n=Number(localStorage.getItem('estgar_quote_seq')||0)+1;return `EST-${new Date().getFullYear()}-${String(n).padStart(4,'0')}`}
function setQuoteNumber(){['quoteNumber','summaryQuoteNumber'].forEach(id=>$(id).textContent=state.quoteNumber)}
function storageGet(key,fallback){try{const v=localStorage.getItem(key);return v==null?fallback:v}catch(err){console.warn('No se pudo leer almacenamiento local',key,err);return fallback}}
function storageSet(key,value){try{localStorage.setItem(key,value);return true}catch(err){console.error('No se pudo guardar en almacenamiento local',key,err);return false}}
function storageRemove(key){try{localStorage.removeItem(key);return true}catch(err){console.error('No se pudo eliminar del almacenamiento local',key,err);return false}}
function quotes(){try{return JSON.parse(storageGet('estgar_quotes','[]'))||[]}catch{return[]}}
function clients(){try{return JSON.parse(storageGet('estgar_clients','[]'))||[]}catch{return[]}}
function saveClients(arr){if(!storageSet('estgar_clients',JSON.stringify(arr)))throw new Error('El navegador no permitió guardar los clientes en este dispositivo.')}

function clientKey(c){return (c.rut||c.name||c.phone||c.email||'').trim().toLowerCase()}
function upsertClient(c){if(!c.name)return;const arr=clients();const key=clientKey(c);const idx=arr.findIndex(x=>clientKey(x)===key || (x.name||'').trim().toLowerCase()===c.name.trim().toLowerCase());if(idx>=0){arr[idx]={...arr[idx],...c,updatedAt:new Date().toISOString()}}else{arr.push({id:'CLI-'+Date.now(),...c,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}saveClients(arr)}
function migrateClients(){const existing=clients();if(existing.length)return;const map=new Map();quotes().forEach(q=>{if(q.client?.name){const k=clientKey(q.client);if(!map.has(k))map.set(k,{id:'CLI-'+Date.now()+'-'+map.size,...q.client,createdAt:q.date,updatedAt:q.date})}});if(map.size)saveClients([...map.values()])}
function renderServices(){const list=$('serviceCards');list.innerHTML='';Object.entries(pricing).forEach(([id,s])=>{if(id==='web'){}const el=document.createElement('button');el.type='button';el.className='service';el.dataset.id=id;el.innerHTML=`<div><h4>${s.name}</h4><p>${s.description||'Servicio profesional ESTGAR Studio.'}</p></div><span class="toggle"></span>`;el.onclick=()=>toggleService(id,el);list.appendChild(el)})}
function toggleService(id,el){state.services.has(id)?state.services.delete(id):state.services.add(id);el.classList.toggle('active',state.services.has(id));if(id==='web')$('webConfig').classList.toggle('hidden',!state.services.has('web'));renderWebExtras();renderSummary()}
function renderWebExtras(){const wrap=$('webExtras');wrap.innerHTML='';if(!pricing.web)return;pricing.web.extras.forEach(x=>{const l=document.createElement('label');l.className='extra';l.innerHTML=`<input type="checkbox"> <span>${x.name}</span>`;const c=l.querySelector('input');c.checked=state.extras.has(x.id);c.onchange=()=>{c.checked?state.extras.add(x.id):state.extras.delete(x.id);renderSummary()};wrap.appendChild(l)})}
function webTotal(){if(!state.services.has('web'))return 0;const w=pricing.web;let total=Number(w.base)||0;total+=Math.max(0,state.pages-Number(w.pagesIncluded||1))*Number(w.pagePrice||0);w.extras.forEach(x=>{if(state.extras.has(x.id))total+=Number(x.price)||0});return total}
function items(){const rows=[];state.services.forEach(id=>{if(id==='web'){rows.push({name:`${pricing.web.name} · ${state.pages} ${state.pages===1?'página':'páginas'}`,value:webTotal()})}else rows.push({name:pricing[id].name,value:Number(pricing[id].price)||0})});return rows}
function discountAmount(subtotal){const pct=Math.min(100,Math.max(0,Number(state.discount)||0));return Math.round(subtotal*pct/100)}
function renderSummary(){const rows=items(),wrap=$('summary');wrap.innerHTML='';if(!rows.length){wrap.innerHTML='<div class="summary-empty">Selecciona uno o más servicios para comenzar la cotización.</div>';$('subtotal').textContent=money(0);$('discountAmount').textContent='-'+money(0);$('total').textContent=money(0);renderPrint();return}rows.forEach(r=>{const d=document.createElement('div');d.className='summary-row';d.innerHTML=`<span>${r.name}</span><span>${money(r.value)}</span>`;wrap.appendChild(d)});const subtotal=rows.reduce((a,b)=>a+b.value,0),disc=discountAmount(subtotal),total=subtotal-disc;
$('subtotal').textContent=money(subtotal);$('discountAmount').textContent='-'+money(disc);$('discountLine').classList.toggle('hidden',disc===0);$('total').textContent=money(total);renderPrint()}
function getClient(){return{name:$('clientName').value.trim(),rut:$('clientRut').value.trim(),phone:$('clientPhone').value.trim(),email:$('clientEmail').value.trim(),notes:$('clientNotes').value.trim()}}
function saveQuote(){
  try{
    const c=getClient(),rows=items();
    if(!c.name){alert('Ingresa el nombre o empresa del cliente.');return false}
    if(!rows.length){alert('Selecciona al menos un servicio antes de guardar.');return false}
    const subtotal=rows.reduce((a,b)=>a+(Number(b.value)||0),0);
    const discount=discountAmount(subtotal);
    const net=Math.max(0,subtotal-discount);
    const iva=state.applyIva?Math.round(net*0.19):0;
    const total=net+iva;
    const editingId=state.editingQuoteId;
    const q={id:editingId||state.quoteNumber,date:new Date().toISOString(),client:c,items:rows,subtotal,discountPercent:Number(state.discount)||0,discount,net,iva,total,documentType:state.documentType,applyIva:state.applyIva,config:{pages:state.pages,services:[...state.services],extras:[...state.extras]}};
    const arr=quotes();
    if(editingId){const i=arr.findIndex(x=>x.id===editingId);if(i>=0)arr[i]=q;else arr.unshift(q)}
    else{arr.unshift(q);}
    const savedQuotes=arr.slice(0,100);
    if(!storageSet('estgar_quotes',JSON.stringify(savedQuotes))){throw new Error('El navegador rechazó el almacenamiento local. Si estás usando navegación privada, desactívala o permite almacenamiento para esta página.')}
    if(!editingId) storageSet('estgar_quote_seq',String(Number(storageGet('estgar_quote_seq','0'))+1));
    const verify=quotes().find(x=>x.id===q.id);
    if(!verify) throw new Error('La cotización no pudo verificarse después de guardarla.');
    upsertClient(c);
    state.editingQuoteId=null;
    renderAll();
    showView('history');
    alert(`Cotización ${q.id} ${editingId?'actualizada':'guardada'} correctamente.`);
    return true;
  }catch(err){
    console.error('Error al guardar cotización:',err);
    alert('No se pudo guardar la cotización. Verifica que el navegador permita el almacenamiento local e inténtalo nuevamente.');
    return false;
  }
}
function selectedDetails(){
  const details=[];
  state.services.forEach(id=>{
    const s=pricing[id];
    if(!s)return;
    if(id==='web'){
      const extras=pricing.web.extras.filter(x=>state.extras.has(x.id));
      details.push({title:pricing.web.name,description:pricing.web.description||'Desarrollo de sitio web profesional y responsive.',bullets:[`Cantidad de páginas: ${state.pages}`,`Páginas incluidas en la tarifa base: ${pricing.web.pagesIncluded||1}`,...extras.map(x=>`Sección / extra activado: ${x.name}`)]});
    }else{
      details.push({title:s.name,description:s.description||'Servicio profesional ESTGAR Studio.',bullets:[]});
    }
  });
  return details;
}
function bankData(){try{return JSON.parse(localStorage.getItem('estgar_bank')||'{}')}catch{return{}}}
function taxAmount(base){return state.applyIva?Math.round(base*0.19):0}
function quoteData(){
  const c=getClient(),rows=items(),subtotal=rows.reduce((a,b)=>a+b.value,0),discount=discountAmount(subtotal),net=subtotal-discount,iva=taxAmount(net),total=net+iva;
  return {client:c,rows,subtotal,discount,net,iva,total,details:selectedDetails(),documentType:state.documentType,applyIva:state.applyIva,bank:bankData()};
}
function pdfSafe(str){
  const map={'€':'\\200','á':'\\341','é':'\\351','í':'\\355','ó':'\\363','ú':'\\372','ñ':'\\361','Á':'\\301','É':'\\311','Í':'\\315','Ó':'\\323','Ú':'\\332','Ñ':'\\321','ü':'\\374','Ü':'\\334','¿':'\\277','¡':'\\241','·':'\\267','°':'\\260','–':'-','—':'-','“':'"','”':'"','‘':"'",'’':"'",'•':'-'};
  let out=String(str??'').replace(/\\/g,'\\\\');
  out=out.replace(/[€áéíóúñÁÉÍÓÚÑüÜ¿¡·°–—“”‘’•]/g,ch=>map[ch]||ch);
  return out.replace(/[()]/g,m=>'\\'+m);
}
function wrapText(text,max=88){
  const words=String(text??'').split(/\s+/);const lines=[];let line='';
  words.forEach(w=>{if(!line){line=w;return}if((line+' '+w).length<=max)line+=' '+w;else{lines.push(line);line=w}});if(line)lines.push(line);return lines;
}
const PDF_LOGO_JPEG_B64="";
const PRINT_LOGO_DATA_URL="data:image/png;base64,";
function b64Bytes(b64){const bin=atob(b64);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out}
function asciiBytes(s){return new TextEncoder().encode(s)}
function concatBytes(parts){let n=0;parts.forEach(p=>n+=p.length);const out=new Uint8Array(n);let o=0;parts.forEach(p=>{out.set(p,o);o+=p.length});return out}
function makePdfBlob(){
  const d=quoteData(),now=new Date().toLocaleDateString('es-CL'),W=595,H=842,margin=42;
  let y=H-48;const cmds=[];
  const text=(str,x,yy,size=10,bold=false)=>cmds.push(`BT /${bold?'F2':'F1'} ${size} Tf ${x} ${yy} Td (${pdfSafe(str)}) Tj ET`);
  const line=(x1,y1,x2,y2)=>cmds.push(`${x1} ${y1} m ${x2} ${y2} l S`);
  const pageBreak=()=>{cmds.push('0 0 m 0 0 l S');y=H-48;text('ESTGARSTUDIO SpA',margin,y,9,true);y-=22};
  const heading=(str)=>{if(y<70)pageBreak();text(str,margin,y,13,true);y-=20};
  // Logo + header
  cmds.push('q 58 740 58 58 cm /Im1 Do Q');
  text('ESTGARSTUDIO SpA',128,H-48,18,true);text('RUT 78.515.457-6',128,H-68,9);text((d.documentType==='factura'?'FACTURA':(d.documentType==='boleta'?'BOLETA':'COTIZACIÓN'))+' '+state.quoteNumber,128,H-84,10,true);text('Fecha: '+now,W-170,H-84,9);y=H-112;
  line(margin,y,W-margin,y);y-=22;
  text('DATOS DE ESTGAR',margin,y,9,true);y-=15;text('ESTGARSTUDIO SpA · RUT 78.515.457-6',margin,y,9);y-=13;text('Comuna de Paihuano, Región de Coquimbo, Chile',margin,y,8);y-=13;text('Tel. +569 6598 2665 · estgarstudio@gmail.com',margin,y,8);y-=20;
  const b=d.bank||{};if(b.bank||b.accountNumber||b.holder){text('DATOS BANCARIOS',margin,y,9,true);y-=14;const bankLine=[b.bank,b.accountType,b.accountNumber].filter(Boolean).join(' · ');if(bankLine){text(bankLine,margin,y,8);y-=13}const holder=[b.holder,b.holderRut].filter(Boolean).join(' · ');if(holder){text('Titular: '+holder,margin,y,8);y-=13}if(b.transferEmail){text('Transferencias: '+b.transferEmail,margin,y,8);y-=13}y-=8}
  line(margin,y,W-margin,y);y-=20;text('CLIENTE',margin,y,9,true);y-=15;text(d.client.name||'Sin nombre',margin,y,12,true);y-=14;const contact=[d.client.rut,d.client.phone,d.client.email].filter(Boolean).join(' · ');if(contact){text(contact,margin,y,8);y-=15}
  if(d.client.notes){text('Observaciones del proyecto',margin,y,9,true);y-=14;wrapText(d.client.notes,92).forEach(l=>{if(y<60)pageBreak();text(l,margin,y,8);y-=12})}
  y-=8;heading('ALCANCE DEL TRABAJO');
  d.details.forEach(det=>{if(y<100)pageBreak();text(det.title,margin,y,11,true);y-=15;wrapText(det.description,88).forEach(l=>{if(y<60)pageBreak();text(l,margin+8,y,8);y-=12});det.bullets.forEach(b=>{if(y<60)pageBreak();text('- '+b,margin+12,y,8);y-=12});y-=7});
  if(y<150)pageBreak();heading('DETALLE ECONÓMICO');d.rows.forEach(r=>{if(y<60)pageBreak();text(r.name,margin,y,8);text(money(r.value),W-145,y,8,true);y-=15});y-=4;line(margin,y,W-margin,y);y-=17;text('Subtotal',W-210,y,8);text(money(d.subtotal),W-145,y,8,true);y-=15;if(d.discount){text(`Descuento (${state.discount}%)`,W-210,y,8);text('-'+money(d.discount),W-145,y,8,true);y-=15}if(d.applyIva){text('Neto',W-210,y,8);text(money(d.net),W-145,y,8,true);y-=15;text('IVA 19%',W-210,y,8);text(money(d.iva),W-145,y,8,true);y-=15}text('TOTAL',W-210,y,11,true);text(money(d.total),W-145,y,11,true);y-=24;text('Documento generado desde el sistema interno de ESTGAR Studio.',margin,y,7);y-=11;text('ESTGARSTUDIO SpA · RUT 78.515.457-6 · +569 6598 2665 · estgarstudio@gmail.com',margin,y,7);
  const stream=cmds.join('\n');const jpg=b64Bytes(PDF_LOGO_JPEG_B64);const objs=[];const add=x=>{objs.push(typeof x==='string'?asciiBytes(x):x);return objs.length};
  add('<< /Type /Catalog /Pages 2 0 R >>');
  add('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  add('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> /XObject << /Im1 7 0 R >> >> /Contents 4 0 R >>');
  add(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');add(concatBytes([asciiBytes(`<< /Type /XObject /Subtype /Image /Width 1254 /Height 1254 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`),jpg,asciiBytes('\nendstream')]));
  const header=asciiBytes('%PDF-1.4\n'),chunks=[header],offs=[0];let pos=header.length;objs.forEach((o,i)=>{const prefix=asciiBytes(`${i+1} 0 obj\n`),suffix=asciiBytes('\nendobj\n');offs[i+1]=pos;chunks.push(prefix,o,suffix);pos+=prefix.length+o.length+suffix.length});const xrefPos=pos;let xref=`xref\n0 ${objs.length+1}\n0000000000 65535 f \n`;for(let i=1;i<offs.length;i++)xref+=String(offs[i]).padStart(10,'0')+' 00000 n \n';xref+=`trailer\n<< /Size ${objs.length+1} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF`;chunks.push(asciiBytes(xref));return new Blob(chunks,{type:'application/pdf'});
}

async function whatsapp(){
  const c=getClient(),rows=items();
  if(!c.name){alert('Ingresa el nombre o empresa del cliente.');return}
  if(!rows.length){alert('Selecciona al menos un servicio.');return}
  if(!c.phone){alert('Ingresa el teléfono del cliente.');return}
  const blob=makePdfBlob();
  const fileName=`ESTGAR-Cotizacion-${state.quoteNumber}.pdf`;
  const file=new File([blob],fileName,{type:'application/pdf'});
  const textMsg=`Cotización ${state.quoteNumber} de ESTGAR Studio para ${c.name}. Se adjunta el PDF con el detalle del trabajo, servicios y secciones activadas.`;
  if(navigator.share && navigator.canShare && navigator.canShare({files:[file]})){
    try{await navigator.share({title:`Cotización ${state.quoteNumber} · ESTGAR Studio`,text:textMsg,files:[file]});return}catch(e){if(e?.name==='AbortError')return}
  }
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fileName;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
  window.open(`https://wa.me/${c.phone.replace(/\D/g,'')}?text=${encodeURIComponent(textMsg+' El PDF se descargó en tu dispositivo; adjúntalo como documento en WhatsApp.')}`,'_blank');
}

